import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {DatabaseDefinitions} from '../../packages/core/src/database-definitions.js';
import type {ConnectionManager} from '../../packages/core/src/connections.js';
import type {DefinitionPreviewResult,DefinitionSnapshot} from '../../packages/protocol/src/index.js';
import {ddlQuote} from '../../packages/core/src/ddl-syntax.js';
const reviewed=(r:DefinitionPreviewResult)=>{assert.equal(r.kind,'preview');if(r.kind!=='preview')throw new Error('Expected preview');return r.preview;};
export async function definitionContract(manager:ConnectionManager,id:string){
 const service=new DatabaseDefinitions(manager),base=await manager.connect(id),driver=base.profile.driver,mysql=driver==='mysql'||driver==='mariadb',schema=mysql?base.profile.database!:'public',q=(n:string)=>ddlQuote(n,driver),qualified=(n:string)=>q(schema)+'.'+q(n),prefix='def_'+randomUUID().replaceAll('-','').slice(0,10),table=prefix+'_t',view=prefix+'_v',func=prefix+'_f',proc=prefix+'_p',trigger=prefix+'_tr',audit=prefix+'_a';
 const read=async(name:string,kind:string)=>{const ref=(await service.list(id,schema)).find(r=>r.kind===kind&&(r.name===name||r.name.startsWith(name+'(')));assert(ref,`Catalog ${kind} ${name}`);const b=await service.read(id,ref);assert(b);return b;};
 const apply=async(b:DefinitionSnapshot,text:string)=>{const p=reviewed(await service.preview(b,text));assert.equal(p.policy,mysql?'implicit-commit':'transactional');const r=await service.apply(id,p.token);assert.equal(r.status,'succeeded',r.error);assert(r.snapshot);return r.snapshot;};
 await base.query(`CREATE TABLE ${qualified(table)}(id INT PRIMARY KEY,v VARCHAR(80))`);await base.query(`INSERT INTO ${qualified(table)} VALUES(1,'before')`);await base.query(`CREATE TABLE ${qualified(audit)}(v VARCHAR(80))`);
 try{
  await base.query(`CREATE VIEW ${qualified(view)}${mysql?'':' WITH (security_barrier=true,security_invoker=true)'} AS SELECT id,v FROM ${qualified(table)} WHERE id>0${mysql?'':' WITH LOCAL CHECK OPTION'}`);
  let b=await read(view,'view');const editedView=b.sql.replace(/>\s*0\b/,'> 1');assert.notEqual(editedView,b.sql,'The fixture must edit the server-normalized view SQL');let p=reviewed(await service.preview(b,editedView));assert.equal((await base.query(`SELECT count(*) FROM ${qualified(view)}`)).rows[0]?.c0,1);
  let r=await service.apply(id,p.token);assert.equal(r.status,'succeeded',r.error);assert.equal((await base.query(`SELECT count(*) FROM ${qualified(view)}`)).rows[0]?.c0,0);
  if(!mysql){assert.match(r.snapshot!.rawSql,/security_invoker=true/);assert.match(r.snapshot!.rawSql,/check_option=local/);}
  const stale=await read(view,'view');p=reviewed(await service.preview(stale,stale.sql));await base.query(`CREATE OR REPLACE VIEW ${qualified(view)} AS SELECT id,v FROM ${qualified(table)} WHERE id>2`);assert.equal((await service.preview(stale,stale.sql)).kind,'conflict');r=await service.apply(id,p.token);assert.equal(r.status,'failed');assert.match(r.error!,/changed after preview/);
  if(mysql){
   await base.query(`CREATE FUNCTION ${qualified(func)}(n INT) RETURNS INT DETERMINISTIC RETURN n+1`);b=await read(func,'function');const noChange=reviewed(await service.preview(b,b.sql));assert.deepEqual(noChange.steps,[]);assert.equal((await service.apply(id,noChange.token)).completed,0);b=await apply(b,b.sql.replace(/n\s*\+\s*1/,'n+2'));assert.equal((await base.query(`SELECT ${qualified(func)}(3)`)).rows[0]?.c0,5);
   const originalCollation=String((await base.query('SELECT @@SESSION.collation_connection')).rows[0]?.c0);await base.query("SET SESSION collation_connection='utf8mb4_bin'");try{await base.query(`CREATE PROCEDURE ${qualified(proc+'_ctx')}() SELECT 'context'`);}finally{await base.query("SET SESSION collation_connection='"+originalCollation+"'");}const context=await read(proc+'_ctx','procedure');assert.equal(context.editable,false);assert(context.notes.some(n=>n.includes('creation context')));await assert.rejects(service.preview(context,context.sql),/reference only/);
   await base.query(`CREATE PROCEDURE ${qualified(proc)}(IN n INT,OUT result INT) BEGIN SET result=n+1; END`);b=await read(proc,'procedure');b=await apply(b,b.sql.replace(/n\s*\+\s*1/,'n+2'));await base.query(`CALL ${qualified(proc)}(3,@answer)`);assert.equal((await base.query('SELECT @answer')).rows[0]?.c0,5);
   await base.query(`CREATE TRIGGER ${qualified(trigger)} AFTER UPDATE ON ${qualified(table)} FOR EACH ROW INSERT INTO ${qualified(audit)} VALUES(CONCAT(NEW.v,'-first'))`);
   await base.query(`CREATE TRIGGER ${qualified(trigger+'_second')} AFTER UPDATE ON ${qualified(table)} FOR EACH ROW FOLLOWS ${q(trigger)} INSERT INTO ${qualified(audit)} VALUES(CONCAT(NEW.v,'-second'))`);
   b=await read(trigger,'trigger');await apply(b,b.sql.replace('-first','-changed'));await base.query(`UPDATE ${qualified(table)} SET v='edited'`);assert.deepEqual((await base.query(`SELECT v FROM ${qualified(audit)}`)).rows.map(r=>r.c0),['edited-changed','edited-second']);
   b=await read(trigger,'trigger');await apply(b,b.sql.replace(/AFTER\s+UPDATE/i,'BEFORE DELETE').replace(/NEW\.v/gi,'OLD.v'));await base.query(`DELETE FROM ${qualified(table)} WHERE id=1`);assert.equal((await base.query(`SELECT count(*) FROM ${qualified(audit)} WHERE v='edited-changed'`)).rows[0]?.c0,2);
   // MySQL DROP/CREATE failure is honestly partial. MariaDB's OR REPLACE is
   // server-specific; the report must never claim a client rollback either.
   b=await read(func,'function');p=reviewed(await service.preview(b,b.sql.replace(/RETURN n\s*\+\s*2/i,'RETURN invalid syntax !!!')));r=await service.apply(id,p.token);assert.equal(r.status,'failed');assert.equal(r.rolledBack,false);if(driver==='mysql'){assert.equal(r.objectExists,false);assert(r.completed>=2);assert(r.committed,'The acknowledged DROP was committed even though CREATE failed.');}
  }else{
   await base.query(`CREATE FUNCTION ${qualified(func)}(n integer DEFAULT 1) RETURNS integer LANGUAGE SQL AS $$ SELECT n+1 $$`);b=await read(func,'function');b=await apply(b,b.sql.replace('n+1','n+2'));assert.equal((await base.query(`SELECT ${qualified(func)}(3)`)).rows[0]?.c0,5);await assert.rejects(service.preview(b,b.sql.replace('n integer','n bigint')),/signature/);
   await base.query(`CREATE PROCEDURE ${qualified(proc)}(n integer) LANGUAGE SQL AS $$ INSERT INTO ${qualified(audit)} VALUES(n::text) $$`);b=await read(proc,'procedure');await apply(b,b.sql.replace('n::text',"(n+1)::text"));await base.query(`CALL ${qualified(proc)}(3)`);assert.equal((await base.query(`SELECT v FROM ${qualified(audit)}`)).rows[0]?.c0,'4');await base.query(`DELETE FROM ${qualified(audit)}`);
   await base.query(`CREATE FUNCTION ${qualified(prefix+'_tf')}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO ${qualified(audit)} VALUES(NEW.v); RETURN NEW; END $$`);await base.query(`CREATE TRIGGER ${q(trigger)} AFTER UPDATE ON ${qualified(table)} FOR EACH ROW EXECUTE FUNCTION ${qualified(prefix+'_tf')}()`);await base.query(`ALTER TABLE ${qualified(table)} DISABLE TRIGGER ${q(trigger)}`);
   await base.query(`COMMENT ON TRIGGER ${q(trigger)} ON ${qualified(table)} IS 'retained comment'`);b=await read(trigger,'trigger');const previousId=b.ref.id;b=await apply(b,b.sql.replace('FOR EACH ROW','FOR EACH ROW WHEN (true)'));assert.equal(b.triggerState,'D');assert.notEqual(b.ref.id,previousId);assert(b.extras.some(e=>e.sql.includes('retained comment')));await base.query(`UPDATE ${qualified(table)} SET v='edited'`);assert.equal((await base.query(`SELECT count(*) FROM ${qualified(audit)}`)).rows[0]?.c0,0);
   p=reviewed(await service.preview(await read(func,'function'),b.rawSql?'CREATE FUNCTION '+qualified(func)+'(n integer DEFAULT 1) RETURNS integer LANGUAGE SQL AS $$ SELECT invalid syntax !!! $$':''));r=await service.apply(id,p.token);assert.equal(r.status,'failed');assert(r.rolledBack);assert.equal((await base.query(`SELECT ${qualified(func)}(3)`)).rows[0]?.c0,5);
  }
 }finally{
  if(mysql){for(const [kind,name] of [['TRIGGER',trigger],['TRIGGER',trigger+'_second'],['FUNCTION',func],['PROCEDURE',proc],['PROCEDURE',proc+'_ctx'],['VIEW',view],['TABLE',audit],['TABLE',table]])await base.query(`DROP ${kind} IF EXISTS ${qualified(name!)}`);}
  else{for(const sql of [`DROP VIEW IF EXISTS ${qualified(view)}`,`DROP TABLE IF EXISTS ${qualified(table)} CASCADE`,`DROP FUNCTION IF EXISTS ${qualified(prefix+'_tf')}()`,`DROP FUNCTION IF EXISTS ${qualified(func)}(integer)`,`DROP PROCEDURE IF EXISTS ${qualified(proc)}(integer)`,`DROP TABLE IF EXISTS ${qualified(audit)}`])await base.query(sql);}
 }
}
